const fs = require('fs');
const path = require('path');

const SCRIPT = 'json-ts-types.js';

// The wasm-pack `.d.ts` is REWRITTEN IN PLACE, so the appended block is delimited by this marker
// and truncated at the start of every run: without it a second run (one not preceded by
// `rimraf ./pkg`) appends a second copy of every declaration and TypeScript reports TS2300 on each.
const MARKER =
  '// cddl-codegen:json-types (generated by json-ts-types.js; regenerated each run - do not edit below)';

// The JSON method name cddl-codegen emits by default. Under `--wasm-cbor-json-api-macro` the tool
// emits a macro CALL and the macro body (yours) names the methods, so the name has to be passed in.
const DEFAULT_METHOD = 'to_json_value';

// LOCKSTEP (argument convention + root/wasm-dir resolution): the `--name=value` parser and the
// `resolveRoot`/`resolveWasmDir` pair below are mirrored verbatim in `run-json2ts.js`. The
// generator ships exactly these two self-contained files (`--package-json --json-schema-export`, or
// `--json-schema-scripts` on its own), so neither may `require` the other — a change to one must be
// mirrored into the other in the same commit.
function parseArgs(script, argv, known) {
  const out = {};
  for (const arg of argv) {
    const m = /^--([\w-]+)=(.*)$/.exec(arg);
    if (m == null || !known.includes(m[1])) {
      // A typo'd override must not silently fall back to the default and generate against the
      // wrong tree, so an unrecognized argument is fatal rather than ignored.
      console.error(
        `${script}: unrecognized argument ${JSON.stringify(arg)}. Supported: ` +
        known.map(k => `--${k}=<value>`).join(', '));
      process.exit(1);
    }
    out[m[1]] = m[2];
  }
  return out;
}

// Both shipped layouts place the scripts at `<root>/scripts/*.js`, so the root is derivable from
// the script's own location — no dependence on the caller's cwd.
function resolveRoot(override) {
  return override != null ? path.resolve(override) : path.resolve(__dirname, '..');
}

// `--package-json` nests the crates one level deeper (`<root>/rust/wasm`); the bare
// `--json-schema-scripts` layout puts the wasm crate at `<root>/wasm`.
function resolveWasmDir(script, root, override) {
  if (override != null) {
    const dir = path.resolve(override);
    if (!fs.existsSync(dir)) {
      console.error(`${script}: --wasm-dir=${dir} does not exist`);
      process.exit(1);
    }
    return dir;
  }
  const candidates = [path.join(root, 'rust', 'wasm'), path.join(root, 'wasm')];
  const found = candidates.find(candidate => fs.existsSync(candidate));
  if (found == null) {
    console.error(
      `${script}: could not find the wasm crate directory. Looked for:\n  ` +
      candidates.join('\n  ') +
      `\n(root resolved to ${root}). Pass --wasm-dir=<dir>, or --root=<dir>, to override.`);
    process.exit(1);
  }
  return found;
}
// end LOCKSTEP block

// wasm-pack names the `.d.ts` after the crate, so it tracks `--lib-name`; discover it instead of
// hardcoding one name. `<crate>_bg.wasm.d.ts` is wasm-pack's own sidecar, never the bindings file.
function resolveDts(script, wasmDir, override) {
  if (override != null) {
    const file = path.resolve(override);
    if (!fs.existsSync(file)) {
      console.error(`${script}: --dts=${file} does not exist`);
      process.exit(1);
    }
    return file;
  }
  const pkgDir = path.join(wasmDir, 'pkg');
  if (!fs.existsSync(pkgDir)) {
    console.error(
      `${script}: no wasm-pack output at ${pkgDir}. Run \`wasm-pack build\` first, or pass ` +
      `--dts=<path/to/bindings.d.ts>.`);
    process.exit(1);
  }
  const candidates = fs.readdirSync(pkgDir)
    .filter(file => file.endsWith('.d.ts') && !file.endsWith('_bg.wasm.d.ts'))
    .sort();
  if (candidates.length !== 1) {
    console.error(
      `${script}: expected exactly one wasm-pack .d.ts in ${pkgDir}, found ${candidates.length}` +
      (candidates.length === 0 ? '' : `:\n  ${candidates.join('\n  ')}`) +
      `\nPass --dts=<path/to/bindings.d.ts> to pick one.`);
    process.exit(1);
  }
  return path.join(pkgDir, candidates[0]);
}

const args = parseArgs(SCRIPT, process.argv.slice(2), ['root', 'wasm-dir', 'dts', 'method', 'allow-untyped']);
const root = resolveRoot(args.root);
const wasmDir = resolveWasmDir(SCRIPT, root, args['wasm-dir']);
const dtsFile = resolveDts(SCRIPT, wasmDir, args.dts);
const method = args.method != null && args.method !== '' ? args.method : DEFAULT_METHOD;
if (!/^[A-Za-z_$][\w$]*$/.test(method)) {
  console.error(`${SCRIPT}: --method=${JSON.stringify(method)} is not a valid identifier`);
  process.exit(1);
}

const jsonDefsFile = path.join(wasmDir, 'json-gen', 'output', 'json-types.d.ts');
if (!fs.existsSync(jsonDefsFile)) {
  console.error(
    `${SCRIPT}: no emitted TypeScript defs at ${jsonDefsFile}. Run run-json2ts.js first.`);
  process.exit(1);
}
const jsonDefs = fs.readFileSync(jsonDefsFile, 'utf8');

// Only names this file actually DECLARES may be spliced into the bindings: renaming `any` to a type
// nothing declares trades a lossy-but-valid `any` for a TS2304 dangling reference. So a class the
// document publishes no type for is never spliced — it FAILS the run (see the untyped-class check
// at the bottom), and keeps its `any` only under an explicit `--allow-untyped=<Class>` exception.
const declared = new Set();
for (const m of jsonDefs.matchAll(/^export\s+(?:type|interface)\s+(\w+)/gm)) {
  declared.add(m[1]);
}

// Truncate any previously-appended block before doing anything else, so the pass below never scans
// the appended defs and repeated runs are a fixed point.
const raw = fs.readFileSync(dtsFile, 'utf8');
const markerAt = raw.indexOf(MARKER);
const lines = (markerAt >= 0 ? raw.slice(0, markerAt) : raw).trimEnd().split(/\r?\n/);

const methodRegex = new RegExp(`(\\s?${method}\\(\\)\\s?:\\s?)(any)(;)`);
const jsDocRegex = /(\s?\*\s?\@returns\s\{)(any)(\})/;
// A zero-argument method declared to return `any` — the shape the specialization targets, whatever
// it happens to be named. Used only for the diagnostic below.
const anyMethodRegex = /^\s*(?:static\s+)?[A-Za-z_$][\w$]*\(\)\s*:\s*any\s*;/;

let currentClass = null;
const specialized = new Set();
const anyMethods = new Map();
const untypedClasses = new Map();
for (let i = 0; i < lines.length; ++i) {
  const line = lines[i];
  const classDef = /export class(.*){/.exec(line);
  if (classDef != null && classDef.length > 1) {
    currentClass = classDef[1].trim();
    continue;
  }
  // A closing brace in column 0 ends the class body. Without this (and the null guard below) a
  // match outside any class would splice the literal `nullJSON`, or the previous class's name.
  if (/^\}/.test(line)) {
    currentClass = null;
    continue;
  }
  if (currentClass == null) {
    continue;
  }
  if (anyMethodRegex.test(line)) {
    if (!anyMethods.has(currentClass)) {
      anyMethods.set(currentClass, []);
    }
    anyMethods.get(currentClass).push(line.trim());
  }
  const jsonType = `${currentClass}JSON`;
  if (!declared.has(jsonType)) {
    // The bindings declare the JSON method but the document published no type for this class:
    // the splice has nothing to write, so without the check below the method would ship `any`
    // with nothing said. Recorded here, judged after the loop.
    if (methodRegex.test(line)) {
      untypedClasses.set(currentClass, line.trim());
    }
    continue;
  }
  let next = line.replace(methodRegex, `$1${jsonType}$3`);
  if (next === line) {
    next = line.replace(jsDocRegex, `$1${jsonType}$3`);
  }
  if (next !== line) {
    lines[i] = next;
    specialized.add(currentClass);
  }
}

// The failure this catches: the emitted schemas and the bindings both exist, but the method name
// the specialization looks for is not the one the bindings declare (the `--wasm-cbor-json-api-macro`
// case, where the macro body names the methods). Every class then silently keeps `any`. The
// condition is per-class and deliberately narrow so it cannot fire on the legitimate zero-rename
// case — `--json-schema-export` without the wasm JSON API declares no `any`-returning method at all.
const unspecialized = [...anyMethods.keys()]
  .filter(cls => declared.has(`${cls}JSON`) && !specialized.has(cls))
  .sort();
if (unspecialized.length > 0) {
  console.error(
    `${SCRIPT}: found no \`${method}\` to specialize in ${unspecialized.length} class(es) that ` +
    `have an emitted JSON type and still declare a zero-argument method returning \`any\`:\n` +
    unspecialized.map(cls =>
      `  ${cls} (${cls}JSON is declared): ${anyMethods.get(cls).join(' ')}`).join('\n') +
    `\n${dtsFile} was left untouched. If your JSON methods are named by a ` +
    `--wasm-cbor-json-api-macro body rather than by cddl-codegen, re-run with --method=<name>.`);
  process.exit(1);
}

// A class whose JSON method ships `any` because the schema document published no type for it
// is the silent-publication mode this pipeline exists to close: nothing fails, nothing warns,
// and the consumer just never gets the type. The fix belongs at the DOCUMENT — a CDDL rule, a
// `--json-schema-root` for a hand-written type, or a `--json-schema-dep` for a dependency's
// classes shipped in this package. A deliberate exception must be spelled out per class with
// `--allow-untyped=<Class>[,<Class>...]`, and a stale exception (the class is typed now, or
// gone) is itself an error so the list cannot rot.
const allowUntyped = new Set((args['allow-untyped'] || '').split(',').filter(Boolean));
const staleAllows = [...allowUntyped].filter(cls => !untypedClasses.has(cls)).sort();
if (staleAllows.length > 0) {
  console.error(
    `${SCRIPT}: --allow-untyped names ${staleAllows.length} class(es) that are not untyped ` +
    `(typed now, renamed, or removed):\n  ${staleAllows.join('\n  ')}\n` +
    `Remove them from the flag. ${dtsFile} was left untouched.`);
  process.exit(1);
}
const untyped = [...untypedClasses.keys()].filter(cls => !allowUntyped.has(cls)).sort();
if (untyped.length > 0) {
  // One offender shape is NOT a missing type: `run-json2ts.js` sets each definition's title to
  // `<key>JSON`, but json2ts normalizes titles into identifiers, so the declaration it emits can
  // differ from the `<Class>JSON` this script keys on (`$defs` key `Blake2b256` -> declaration
  // `Blake2B256JSON`). Telling that consumer to publish a type they have already published is a
  // worse diagnosis than the `any` this check replaced, so name the declaration that exists.
  // Comparing modulo normalization — every non-alphanumeric stripped, case folded — is cheap and
  // catches the whole class without modelling json2ts's exact rules. DIAGNOSTIC ONLY: which classes
  // fail, and the exit code, are unchanged.
  const normalized = name => name.replace(/[^A-Za-z0-9]/g, '').toLowerCase();
  const declaredByNormalized = new Map();
  for (const name of declared) {
    const key = normalized(name);
    if (!declaredByNormalized.has(key)) {
      declaredByNormalized.set(key, []);
    }
    declaredByNormalized.get(key).push(name);
  }
  const nearMisses = new Map();
  for (const cls of untyped) {
    const matches = declaredByNormalized.get(normalized(`${cls}JSON`));
    if (matches != null) {
      nearMisses.set(cls, matches);
    }
  }
  // `--allow-untyped` is the wrong answer for a near miss — the type exists — so those classes are
  // named in the failure but left out of the suggested flag value.
  const allowable = untyped.filter(cls => !nearMisses.has(cls));
  console.error(
    `${SCRIPT}: ${untyped.length} class(es) declare \`${method}(): any\` with no \`<Class>JSON\` ` +
    `declaration in the emitted defs, so they would silently ship untyped:\n` +
    untyped.map(cls => {
      const entry = `  ${cls}: ${untypedClasses.get(cls)}`;
      const matches = nearMisses.get(cls);
      if (matches == null) {
        return entry;
      }
      return `${entry}\n    ^ the document DOES publish a type for this class, declared as ` +
        `${matches.join(' / ')} — that differs from ${cls}JSON only by json2ts's normalization of ` +
        `the definition title into an identifier. --allow-untyped is not the answer here (it would ` +
        `ship \`any\` for a class that has a type): rename the rule, or give it an @name, so the ` +
        `class name is a fixed point of that normalization.`;
    }).join('\n') +
    `\n${dtsFile} was left untouched. Publish a type for each (a CDDL rule, ` +
    `--json-schema-root for a hand-written type, or --json-schema-dep for a dependency whose ` +
    `classes ship in this package)` +
    (allowable.length > 0
      ? `, or record a deliberate exception with --allow-untyped=${allowable.join(',')}.`
      : '.'));
  process.exit(1);
}

fs.writeFileSync(dtsFile, `${lines.join('\n')}\n${MARKER}\n${jsonDefs}`);
